INSERT INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note)
SELECT * FROM (VALUES
  ('mokoloi-prey-stalker-power-armor', 1, 'Hand to Hand Combat', 'Equal to Supernatural P.S. or the 30 supernatural P.S. of the armor, whichever is higher; Body Flip/Throw 1D4 M.D. plus victim loses initiative and one attack', 1, NULL, NULL, NULL, '+2 attacks per melee round, plus one at levels 5 and 10; +2 initiative, +1 at levels 6 and 12; +1 parry (+2 with blades extended); +2 dodge; +1 roll with punch, fall or impact', 'Bonuses apply to Mokoloi trained in the armor. Item 7 of the weapon list.'),
  ('mokoloi-prey-stalker-power-armor', 2, 'Left Arm: Electric Arc', '3D6 M.D.', 1, '200 feet (61 m)', 'Each blast counts as one melee attack/action', 'Effectively unlimited', '+2 to strike (point and shoot)', 'Item 6. Like the Electric Arc spell but slightly more damage and range.'),
  ('mokoloi-prey-stalker-power-armor', 3, 'Sonic Blast (right arm; item 5)', 'Not read: the damage line is on printed page 146, which is missing from the source PDF.', 1, '50 feet (15.2m)', 'Once per melee round; each blast counts as one melee attack/action', 'Effectively unlimited', NULL, 'Only the tail of this entry is on available pages (printed 147): knockdown table. Under 500 lbs: 01-88% knocked down and hurled 3D4 yards/meters, 89+ keeps balance but full damage. 500-1000 lbs: 01-50%, hurled 1D4 yards. Up to one ton: 01-20%, knocked back a few feet. Fliers hurled twice as far, not grounded; may be slammed into walls etc. for extra 1D4 M.D. Fallen: 01-40% drop held item, lose initiative and two attacks; caster and those touching him unaffected; acrobatics/balance skills +10% to save; successful fall/impact roll (14+) halves damage, full penalties. Entry header, damage and purpose lie on missing printed page 146.')
) WHERE NOT EXISTS (SELECT 1 FROM vehicle_weapons WHERE vehicle_slug = 'mokoloi-prey-stalker-power-armor');

