-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 9 Australia vehicle rows are in' AS assertion, count(*) AS got, 9 AS want
  FROM vehicles WHERE slug IN ('mokoloi-prey-stalker-power-armor', 'apaa-rusty-modular-power-armor', 'x50-bushbasher-power-armor', 'nt-1200-devil-4x4', 'nt-6000-crawler-apc', 'slicer-patrol-boat', 'nt-v40-viper-attack-chopper', 'vr-500x-stinger', 'one-and-two-man-fliers') AND source_book LIKE 'Rifts World Book 19: Australia p.%';
SELECT 'three are power armor, one a ship, one a drone' AS assertion, count(*) AS got, 5 AS want
  FROM vehicles WHERE slug IN ('mokoloi-prey-stalker-power-armor', 'apaa-rusty-modular-power-armor', 'x50-bushbasher-power-armor', 'nt-1200-devil-4x4', 'nt-6000-crawler-apc', 'slicer-patrol-boat', 'nt-v40-viper-attack-chopper', 'vr-500x-stinger', 'one-and-two-man-fliers') AND vehicle_class IN ('power-armor', 'ship', 'drone');
SELECT 'their location rows are in' AS assertion, count(*) AS got, 80 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('mokoloi-prey-stalker-power-armor', 'apaa-rusty-modular-power-armor', 'x50-bushbasher-power-armor', 'nt-1200-devil-4x4', 'nt-6000-crawler-apc', 'slicer-patrol-boat', 'nt-v40-viper-attack-chopper', 'vr-500x-stinger', 'one-and-two-man-fliers');
SELECT 'their weapon rows are in, once' AS assertion, count(*) AS got, 35 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('mokoloi-prey-stalker-power-armor', 'apaa-rusty-modular-power-armor', 'x50-bushbasher-power-armor', 'nt-1200-devil-4x4', 'nt-6000-crawler-apc', 'slicer-patrol-boat', 'nt-v40-viper-attack-chopper', 'vr-500x-stinger', 'one-and-two-man-fliers');

